1	/**
2	 * callees.ts — who a run may call, as the list travels from the step that can read
3	 * GitHub to the steps that cannot.
4	 *
5	 * ## Why a file and not a read in each consumer
6	 *
7	 * The participant list comes from the GitHub API, and the step that starts atoma is
8	 * deliberately credential-free: every tool server the agent starts can read that
9	 * process's environment for minutes, so no token is put in it. The read therefore
10	 * happens once, in a step that has a token (`read_callees.ts`), and the answer travels
11	 * in the run directory to the three consumers that need it:
12	 *
13	 *   - `inject_callees_notice.ts`, which names the people to the run so the run can
14	 *     write one of those logins in its closing message;
15	 *   - `check_ending.ts`, which decides whether that message called more than one thing;
16	 *   - `post_result_comment.ts`, which decides which mentions in it may notify.
17	 *
18	 * One file rather than three reads, because those answers have to be the same set by
19	 * construction. Three reads are three answers, and the first time they disagree a run
20	 * is refused for calling somebody it was told about — or, the other way round, a
21	 * mention is escaped while the machinery believes a call was made, and nobody is told
22	 * anything at all.
23	 *
24	 * ## Two lists, because "may mention" and "may call" are not the same question
25	 *
26	 * `participants` is everybody a comment may name without notifying a stranger — the
27	 * thread's people and the collaborators, bots included. `humans` is the subset that
28	 * can take a turn: the same list without bots, plus the owner of the work. A bot is a
29	 * participant; nobody's turn is a bot's.
30	 */
31	import { existsSync, readFileSync } from "node:fs";
32	
33	export interface Callees {
34	  /** Logins a run may call: non-bot participants and the owner, owner first. */
35	  humans: string[];
36	  /** Logins a comment may mention without notifying a stranger: all of them, owner first. */
37	  participants: string[];
38	  /** The login the work belongs to, or `""`. Always one of `humans` when set. */
39	  notify: string;
40	}
41	
42	export const NO_CALLEES: Callees = { humans: [], participants: [], notify: "" };
43	
44	/**
45	 * The list written by `read_callees.ts`, or `NO_CALLEES` when the file is absent or
46	 * unreadable.
47	 *
48	 * Absent is the fail-closed case, and the consequence is the safe one: a mention of
49	 * nobody in particular counts as no call, so a message that names a person is only
50	 * ever refused for something the machinery could actually see. The comment then
51	 * escapes every mention and the machinery mentions the owner itself, so the turn still
52	 * comes back to a person — it is the notification that gets narrower, never the work.
53	 */
54	export function readCalleesFile(path: string | undefined): Callees {
55	  if (!path || !existsSync(path)) return NO_CALLEES;
56	  try {
57	    const parsed = JSON.parse(readFileSync(path, "utf8")) as {
58	      humans?: unknown;
59	      participants?: unknown;
60	      notify?: unknown;
61	    };
62	    const logins = (value: unknown): string[] =>
63	      Array.isArray(value) ? value.filter((login): login is string => typeof login === "string" && login !== "") : [];
64	    return {
65	      humans: logins(parsed.humans),
66	      participants: logins(parsed.participants),
67	      notify: typeof parsed.notify === "string" ? parsed.notify : "",
68	    };
69	  } catch {
70	    // A body that will not parse tells us nothing about who may be called.
71	    return NO_CALLEES;
72	  }
73	}

